<?php
use EIPSI\StudyEngine\Builder as B;
use EIPSI\StudyEngine\Longitudinal as L;
use EIPSI\StudyEngine\Persistence as P;
function po_initial_version(array $base,int $number,callable $edit): string {$d=B\Draft::version($base,$number);$edit($d);$d['state']='PUBLISHED';return (new P\StudyVersionRepository(pf_db()))->publish($d);}
$shared=$GLOBALS['po_fixed_study'];$sharedBase=$shared['definition'];$sharedPublic=$sharedBase['study']['public_id'];$sharedStudy=$sharedBase['study']['logical_id'];$sharedRow=(new P\StudyVersionRepository(pf_db()))->find($shared['id']);$sharedClock=$GLOBALS['pf_now'];$sharedCookies=$_COOKIE;$sharedTime=static function(){return strtotime($GLOBALS['pf_now']);};add_filter('eipsi_runtime_timestamp',$sharedTime,PHP_INT_MAX);
try{
 $sharedF=pf_enroll(array('public'=>$sharedPublic),'shared-initial@example.test',null,null,'America/Argentina/Buenos_Aires');$_COOKIE[L\Identity::cookieName($sharedPublic)]=$sharedF['token'];$sharedNative=EIPSI\StudyEngine\Runtime\NativeBridge::offer($sharedF);$sharedOwner=new EIPSI\AssessmentEditor\Runtime\Owner();$sharedBinding=json_decode($sharedOwner->store->find('executions',$sharedNative['execution_id'])['binding_json'],true);
 $sharedV2=po_initial_version($sharedBase,2,static function(&$d){$c=&$d['protocol_metadata']['longitudinal']['initial_screen'];$c['authentication']['verification']='IMMEDIATE';$c['authentication']['membership_enabled']=true;$c['title_html']='<h1>Shared current initial screen</h1>';$c['authentication']['label']='Shared email label';$d['protocol_metadata']['public_messages']['wait_title']='Shared waiting text';$d['protocol_metadata']['public_messages']['document_title']='Do not replace the pinned general title';foreach($d['nodes'] as &$n)if($n['id']==='TOMORROW')$n['schedule']['temporal_rule']['day_index']=9;unset($n);});
 po_case('All published Initial screen settings apply to an existing V1 participant without activating V2',function()use($sharedBase,$sharedF,$sharedPublic){$effective=L\InitialScreen::effectiveDefinition(pf_db(),$sharedBase);$c=L\Configuration::read($effective);pe_assert($c['initial_screen']['authentication']['verification']==='IMMEDIATE'&&$c['initial_screen']['authentication']['membership_enabled'],'Authentication remained pinned');pe_assert(EIPSI\StudyEngine\Runtime\PublicMessages::text($effective,'wait_title')==='Shared waiting text','Initial message stale');pe_equal($effective['nodes'],$sharedBase['nodes'],'Scientific schedule replaced');pe_assert(EIPSI\StudyEngine\Runtime\PublicMessages::text($effective,'document_title')===EIPSI\StudyEngine\Runtime\PublicMessages::text($sharedBase,'document_title'),'General message replaced');$frame=pf_runtime()->initialFrame($sharedPublic);pe_assert(strpos((new L\EmailTemplate())->screen($frame),'Shared current initial screen')!==false,'Current initial screen not rendered');});
 po_case('Existing runtime and Native authorization enforce the newly published email validation policy',function()use($sharedF,$sharedPublic,$sharedOwner,$sharedBinding){$frame=pf_runtime()->handle($sharedPublic,$sharedF['token']);pe_assert(!empty($frame['verification_required']),'Runtime ignored current verification');pe_reject(function()use($sharedOwner,$sharedBinding){$sharedOwner->store->transaction(function()use($sharedOwner,$sharedBinding){EIPSI\AssessmentEditor\Runtime\Authorization::check($sharedOwner->store,$sharedBinding);});},'Confirmá tu email');});
 po_case('Current confirmation checkbox and validation mode affect old participation without replacing its assessment',function()use($sharedBase,$sharedF,$sharedPublic){po_initial_version($sharedBase,3,static function(&$d){$c=&$d['protocol_metadata']['longitudinal']['initial_screen'];$c['authentication']['verification']='NEVER';$c['authentication']['confirm_after_first']=true;$d['protocol_metadata']['public_messages']['review_body']='Current confirmation description';});$frame=pf_runtime()->handle($sharedPublic,$sharedF['token']);pe_assert($frame['view']['next_action']['kind']==='OPEN_ASSESSMENT','Old participant remained blocked by retired policy');$snapshot=$frame['view']['snapshot'];foreach($snapshot['instances'] as &$i)if($i['definition_id']==='EVENING')$i['state']='COMPLETED';unset($i);$effective=L\InitialScreen::effectiveDefinition(pf_db(),$sharedBase);$config=L\Configuration::read($effective);pe_assert(L\EmailConfirmation::needs(pf_db(),$config,$snapshot,$effective),'Current confirmation flag ignored');pe_assert(EIPSI\StudyEngine\Runtime\PublicMessages::text($effective,'review_body')==='Current confirmation description');});
 $sharedIntent=null;foreach(pf_intents($sharedF['access']['execution_id'],'ASSESSMENT_AVAILABLE') as $intent){$block=$sharedOwner->store->db->row(pf_db()->prepare('SELECT definition_id FROM '.pf_db()->table('block_executions').' WHERE id=%s',$intent['block_execution_id']));if(($block['definition_id']??null)==='TOMORROW')$sharedIntent=$intent;}
 po_case('Disabling current availability notices defers a queued old-version email without sending or cancelling it',function()use($sharedBase,$sharedIntent){pe_assert($sharedIntent!==null,'Future offer missing');po_initial_version($sharedBase,4,static function(&$d){$d['protocol_metadata']['longitudinal']['email_enabled']=false;});$GLOBALS['pf_now']='2026-10-28T00:17:00Z';$before=count($GLOBALS['m0_mail']??array());$result=pf_delivery($sharedIntent);pe_assert(isset($result['defer_until']),'Current disabled policy ignored');$row=array_column(pf_intents($sharedIntent['execution_id']),null,'id')[$sharedIntent['id']];pe_assert($row['state']==='PENDING'&&count($GLOBALS['m0_mail'])===$before,'Disabled offer sent or permanently cancelled');});
 $sharedV5=null;
 po_case('Re-enabled queued old-version offer uses current selected template and its original day-two schedule',function()use($sharedBase,$sharedIntent,&$sharedV5){$sharedV5=po_initial_version($sharedBase,5,static function(&$d){$d['protocol_metadata']['longitudinal']['email_enabled']=true;$d['protocol_metadata']['longitudinal']['immediate_availability_policy']='SEND';$d['protocol_metadata']['longitudinal']['initial_screen']['templates']['ASSESSMENT_AVAILABLE']=array('subject'=>'Current selected template','html'=>'<p>Current selected body.</p>');foreach($d['nodes'] as &$n)if($n['id']==='TOMORROW')$n['schedule']['temporal_rule']['day_index']=9;unset($n);});$before=count($GLOBALS['m0_mail']??array());$result=pf_delivery($sharedIntent);pe_assert($result['success']&&count($GLOBALS['m0_mail'])===$before+1,'Current template not sent at original opportunity');$mail=end($GLOBALS['m0_mail']);pe_assert($mail['subject']==='Current selected template'&&$mail['message']==='<p>Current selected body.</p>','Worker used pinned template');});
 po_case('Unpublished Initial screen edits stay private and stored published V1 protocol stays unchanged',function()use($sharedBase,$sharedV5,$sharedRow,$shared){$svc=new B\Service(pf_db());$source=$svc->load($sharedV5);$draft=$svc->cloneVersion($sharedV5,$source['revision']);$d=$draft['definition'];$d['protocol_metadata']['longitudinal']['initial_screen']['authentication']['verification']='IMMEDIATE';$svc->save($draft['id'],$draft['revision'],'SHARED_INITIAL_PRIVATE_DRAFT',$d);$effective=L\InitialScreen::effectiveDefinition(pf_db(),$sharedBase);pe_assert(L\Configuration::read($effective)['initial_screen']['authentication']['verification']==='NEVER','Draft affected current participants');pe_equal($sharedRow['protocol_json'],(new P\StudyVersionRepository(pf_db()))->find($shared['id'])['protocol_json'],'Published V1 rewritten');});
}finally{$GLOBALS['pf_now']=$sharedClock;$_COOKIE=$sharedCookies;remove_filter('eipsi_runtime_timestamp',$sharedTime,PHP_INT_MAX);}
